        private VoxelBody _body;

        private void Start() => Build();

        /// <summary>
        /// What to build, set from code before <see cref="Build"/> (a generated arena adds the
        /// component and builds it at once). Does nothing once built.
        /// </summary>
        public void Configure(Shape shape, Vector3Int size, int seed)
        {
            if (_body != null)
                return;

            _shape = shape;
            _size = size;
            _seed = seed;
        }

        /// <summary>How wet a material looks (0..1): wet mud glistens, dry mud and muddy grass are damp.</summary>
        private static float Wetness(Material material) => material switch
        {
            Material.MudWet => 1f,
            Material.MudDry => 0.45f,
            Material.MuddyGrass => 0.35f,
            _ => 0f
        };

        /// <summary>A build whose voxel job is running on a worker: <see cref="FinishBuild"/> makes the body.</summary>
        private sealed class PendingBuild
        {
            public JobHandle Handle;
            public NativeArray<byte> Voxels;
            public NativeArray<Color32> Palette;
            public NativeArray<float4> Pads;
            public NativeArray<float4> Streets;
            public int3 Size;
            public int Materials;
            public VoxelTerrainSettings Terrain;
        }

        public void Build()
        {
            PendingBuild pending = BeginBuild();
            if (pending == null)
                return;

            pending.Handle.Complete();
            FinishBuild(pending);
        }

        /// <summary>
        /// Builds several structures at once: their voxel jobs run side by side on the workers (a
        /// generated arena: ground tiles, houses, trees), then each gets its body here, in order.
        /// </summary>
        public static void BuildAll(System.Collections.Generic.IReadOnlyList<VoxelStructure> structures)
        {
            var pending = new PendingBuild[structures.Count];
            for (int i = 0; i < structures.Count; i++)
                pending[i] = structures[i] != null ? structures[i].BeginBuild() : null;
            JobHandle.ScheduleBatchedJobs();

            try
            {
                for (int i = 0; i < structures.Count; i++)
                {
                    PendingBuild build = pending[i];
                    if (build == null)
                        continue;

                    pending[i] = null;
                    build.Handle.Complete();
                    structures[i].FinishBuild(build);
                }
            }
            finally
            {
                // One threw: the jobs still running are waited for and their grids let go.
                foreach (PendingBuild build in pending)
                {
                    if (build == null)
                        continue;

                    build.Handle.Complete();
                    build.Pads.Dispose();
                    build.Streets.Dispose();
                    build.Voxels.Dispose();
                    build.Palette.Dispose();
                }
            }
        }

        /// <summary>The palette and the voxel job, scheduled; null once built.</summary>
        private PendingBuild BeginBuild()
        {
            if (_body != null)
                return null;

            int3 size = math.max(new int3(_size.x, _size.y, _size.z), 1);
            var voxels = new NativeArray<byte>(size.x * size.y * size.z, Allocator.Persistent);
            var palette = new NativeArray<Color32>(256, Allocator.Persistent);

            Color[] colors = { _brick, _mortar, _concrete, _roof, _wood, _mudDry, _mudWet, _grass, _dryGrass, _dirt, _rock, _grassLush, _grassPale, _bark, _leaves, _leavesDark, _needles, _muddyGrass,
                _brickRed, _brickYellow, _stucco, _stone, _trim, _glass, _frame, _door, _slate, _floorWood, _pot,
                _cobble, _joint, _flagstone, _kerb,
                _wallpaper1, _wallpaper2, _wallpaper3, _panel, _furniture, _fabric, _linen, _iron, _carpet, _cobbleWarm, _cobbleDark };
            for (int i = 0; i < colors.Length; i++)
            {
                // Grass varies more from blade to blade than brick from brick.
                var material = (Material)i;
                bool grass = material is Material.Grass or Material.GrassLush or Material.GrassPale or Material.DryGrass
                    or Material.Leaves or Material.LeavesDark or Material.Needles;
                bool plain = material is Material.Glass or Material.Frame or Material.Door;
                bool weathered = material is Material.BrickRed or Material.BrickYellow or Material.Stucco or Material.Trim or Material.Stone;
                MeshVoxelizer.FillShades(palette, 1 + i * MeshVoxelizer.VARIANTS, colors[i],
                    grass ? 0.14f : plain ? 0.02f : weathered ? 0.13f : 0.07f, Wetness(material));
            }

            // A building's load-bearing voxels look the same as the rest: their slots copy the shades.
            if (HasSkeleton)
                for (int k = 0; k < BEARING_MATERIALS; k++)
                for (int v = 0; v < MeshVoxelizer.VARIANTS; v++)
                    palette[BEARING_FIRST + k * MeshVoxelizer.VARIANTS + v] =
                        palette[1 + (int)BearingMaterial(k) * MeshVoxelizer.VARIANTS + v];

            // Ground under a VoxelTerrainSettings follows its hills; on its own it lies flat.
            VoxelTerrainSettings terrain = _shape == Shape.Ground ? GetComponentInParent<VoxelTerrainSettings>() : null;
            Vector4[] padList = terrain != null ? terrain.Pads : null;
            Vector4[] streetList = terrain != null ? terrain.Streets : null;
            var streets = new NativeArray<float4>(math.max(1, streetList?.Length ?? 0), Allocator.TempJob);
            for (int i = 0; streetList != null && i < streetList.Length; i++)
                streets[i] = streetList[i];
            var pads = new NativeArray<float4>(math.max(1, padList?.Length ?? 0), Allocator.TempJob);
            pads[0] = new float4(0f, 0f, -100f, 0f);
            for (int i = 0; padList != null && i < padList.Length; i++)
                pads[i] = padList[i];

            JobHandle handle = new BuildVoxelsJob
            {
                Voxels = voxels,
                Size = size,
                Shape = _shape,
                Seed = (uint)_seed,
                WorldOffset = new int2(Mathf.RoundToInt(transform.position.x / _voxelSize) - size.x / 2,
                    Mathf.RoundToInt(transform.position.z / _voxelSize) - size.z / 2),
                Terrain = terrain != null,
                TerrainShape = terrain != null ? terrain.Shape : default,
                Pads = pads,
                Streets = streets,
                StreetCount = streetList?.Length ?? 0,
                RoadHalf = terrain != null ? terrain.RoadHalfWidth : 0f,
                Verge = terrain != null ? terrain.VergeWidth : 0f,
                VoxelSize = _voxelSize,
                WorldMin = (float3)transform.position + new float3(-size.x * 0.5f, 0f, -size.z * 0.5f) * _voxelSize
            }.Schedule();

            return new PendingBuild
            {
                Handle = handle,
                Voxels = voxels,
                Palette = palette,
                Pads = pads,
                Streets = streets,
                Size = size,
                Materials = colors.Length,
                Terrain = terrain
            };
        }

        /// <summary>The job is done: the body of voxels, its settings and (for buildings) its strength.</summary>
        private void FinishBuild(PendingBuild pending)
        {
            pending.Pads.Dispose();
            pending.Streets.Dispose();
            int3 size = pending.Size;
            NativeArray<byte> voxels = pending.Voxels;
            NativeArray<Color32> palette = pending.Palette;
            VoxelTerrainSettings terrain = pending.Terrain;

            var go = new GameObject("Voxels") { layer = gameObject.layer };
            go.transform.SetParent(transform, false);

            VoxelBodySettings settings = VoxelBodySettings.Default(_voxelSize);
            settings.Origin = new float3(-size.x * 0.5f, 0f, -size.z * 0.5f) * _voxelSize;
            settings.Anchor = VoxelAnchor.Ground;
            settings.Colliders = true;
            settings.Layer = gameObject.layer;
            // Wood and leaves weigh a third of brick: a felled top tips over rather than sinks.
            settings.Density = _shape == Shape.Tree ? 600f : 1800f;
            settings.CraterDepth = _shape == Shape.Ground ? 0.55f : 1f;
            // Rolling ground is a big, mostly empty grid: bigger chunks, far fewer meshes to draw.
            // Blocky ground goes in 64³: it remeshes and cooks on workers without the frame waiting
            // (VoxelWorld), so a bigger chunk costs nothing in the frame, while 625 meshes and
            // colliders become about 170 — fewer draws in every pass (both shadow cascades, depth,
            // depth-normals, forward), in the scene view as well.
            settings.ChunkSize = terrain != null ? (terrain.Smooth ? 32 : 64)
                : _shape is Shape.Tree or Shape.Victorian ? 32 : 0;
            // A crown is ragged: collide with it in 30 cm cells, not voxel by voxel. A house's
            // window frames and trim need no more than 20 cm either.
            settings.ColliderCell = _shape == Shape.Tree ? 3 : _shape == Shape.Victorian ? 2 : 1;
            // Rolling ground is drawn smooth (no 10 cm terraces on the slopes), collides smooth,
            // and is one body too big to flood-fill on every shot: it never looks for loose pieces.
            settings.Smooth = terrain != null && terrain.Smooth;
            settings.Split = terrain == null;
            settings.Terrain = terrain != null;

            _body = go.AddComponent<VoxelBody>();
            _body.Init(size, voxels, palette, settings);
            // Buildings bear their own weight (VoxelBody.SolveStructure): the ground and trees do not.
            if (_shape is Shape.Wall or Shape.House or Shape.Tower or Shape.Victorian)
            {
                _body.SetStrength(BuildStrength(pending.Materials));
                if (HasSkeleton)
                    _body.SetHardness(BuildHardness());
                // A town house's panes, listed once: a blast blows them out (VoxelBody.ShatterGlass).
                if (_shape == Shape.Victorian)
                    _body.SetGlass(1 + (int)Material.Glass * MeshVoxelizer.VARIANTS, MeshVoxelizer.VARIANTS);
                _body.DesignStructure();
            }
        }

        // ---------------------------------------------------------------- skeleton

        /// <summary>
        /// A house, a town house or a tower has a skeleton: its corners and the piers between its
        /// windows, a ring beam round every upper floor and under the eaves, the edges of its floors and the
        /// chimney stacks. They are their own materials in look and in the load solve, but much harder to
        /// bite (BEARING_HARDNESS): bombed, the walls between them fall out and the skeleton stands, as
        /// bombed towns did (user, 2026-11-19).
        /// </summary>
        private bool HasSkeleton => _shape is Shape.House or Shape.Tower or Shape.Victorian;

        /// <summary>How many materials have a load-bearing copy (see BearingMaterial).</summary>
        private const int BEARING_MATERIALS = 14;

        /// <summary>The first palette slot of the load-bearing copies: after every material's shades.</summary>
        private const int BEARING_FIRST = 1 + ((int)Material.CobbleDark + 1) * MeshVoxelizer.VARIANTS;

        /// <summary>A load-bearing voxel's material carries this flag out of the shape functions (see Pick).</summary>
        private const int BEARING = 1 << 16;

        /// <summary>
        /// A load-bearing joint bears this many times the press and the bend of the same material in a wall
        /// between them: 1. What keeps the skeleton is that it is not bitten away; stronger in the load solve, it
        /// held a corner out over a 2.5 m crater (×2 press) or a 2.5 m cantilever (×1.5 bend), where a house must
        /// lose its corner (user, 2026-11-17: the ground under a house holds it up).
        /// </summary>
        private const float BEARING_PRESS = 2f;

        private const float BEARING_BEND = 1f;

        /// <summary>
        /// A bite is this many times smaller in a load-bearing voxel: about 1/8 of the volume. At 3 (1/27) the
        /// skeleton outlasted everything (user, 2026-11-20: three times harder, not fifteen); at 2 it still stands
        /// out of a bombing, and goes under sustained fire.
        /// </summary>
        private const float BEARING_HARDNESS = 2f;

        /// <summary>The k-th material that has a load-bearing copy.</summary>
        private static Material BearingMaterial(int k) => k switch
        {
            0 => Material.BrickRed,
            1 => Material.BrickYellow,
            2 => Material.Stucco,
            3 => Material.Trim,
            4 => Material.Stone,
            5 => Material.Panel,
            6 => Material.Wallpaper1,
            7 => Material.Wallpaper2,
            8 => Material.Wallpaper3,
            9 => Material.Furniture,
            10 => Material.FloorWood,
            11 => Material.Concrete,
            12 => Material.Brick,
            _ => Material.Mortar
        };

        /// <summary>The load-bearing copy of a material (its k), or −1: glass, frames and doors bear nothing.</summary>
        private static int BearingSlot(int material) => material switch
        {
            (int)Material.BrickRed => 0,
            (int)Material.BrickYellow => 1,
            (int)Material.Stucco => 2,
            (int)Material.Trim => 3,
            (int)Material.Stone => 4,
            (int)Material.Panel => 5,
            (int)Material.Wallpaper1 => 6,
            (int)Material.Wallpaper2 => 7,
            (int)Material.Wallpaper3 => 8,
            (int)Material.Furniture => 9,
            (int)Material.FloorWood => 10,
            (int)Material.Concrete => 11,
            (int)Material.Brick => 12,
            (int)Material.Mortar => 13,
            _ => -1
        };

        /// <summary>Per palette entry: 1, or BEARING_HARDNESS for the load-bearing copies.</summary>
        private static NativeArray<float> BuildHardness()
        {
            var hardness = new NativeArray<float>(256, Allocator.Persistent);
            for (int i = 0; i < 256; i++)
                hardness[i] = 1f;
            for (int i = 0; i < BEARING_MATERIALS * MeshVoxelizer.VARIANTS; i++)
                hardness[BEARING_FIRST + i] = BEARING_HARDNESS;
            return hardness;
        }

        /// <summary>
        /// Press (kg) and bend (kg·m) a pair of voxels of each material bears across a face, and the
        /// material's group (pairs of two groups are a seam): see <see cref="VoxelLoad"/>.
        /// </summary>
        private static float3 Strength(Material material) => material switch
        {
            Material.Concrete => new float3(2000f, 80f, 0f),
            Material.Stone or Material.Rock or Material.Kerb or Material.Flagstone => new float3(1500f, 30f, 1f),
            Material.Brick or Material.BrickRed or Material.BrickYellow or Material.Mortar => new float3(1000f, 15f, 2f),
            Material.Stucco or Material.Trim or Material.Wallpaper1 or Material.Wallpaper2 or Material.Wallpaper3
                or Material.Panel => new float3(600f, 20f, 3f),
            Material.Wood or Material.FloorWood or Material.Frame or Material.Door or Material.Carpet => new float3(600f, 400f, 4f),
            // Slates lie on light rafters: a roof spans its own gable (the design pass sees to that), not a corner over nothing.
            Material.Roof or Material.Slate => new float3(300f, 60f, 5f),
            Material.Pot => new float3(300f, 5f, 5f),
            Material.Furniture or Material.Fabric or Material.Linen or Material.Iron => new float3(200f, 50f, 6f),
            Material.Glass => new float3(20f, 0.5f, 7f),
            _ => new float3(600f, 20f, 3f)
        };

        /// <summary>
        /// Every building is this much stronger than its materials' table: at 1 a shell into one wall
        /// or one ram brought a whole house down (user, 2026-11-17: "two or three times stronger").
        /// </summary>
        private const float TOUGHER = 2.5f;

        /// <summary>The strength of every palette entry: each material's shades, and plaster for slots painted later (mud).</summary>
        private static NativeArray<float3> BuildStrength(int materials)
        {
            var strength = new NativeArray<float3>(256, Allocator.Persistent);
            float3 plaster = new float3(600f * TOUGHER, 20f * TOUGHER, 3f);
            for (int i = 0; i < 256; i++)
                strength[i] = plaster;
            for (int m = 0; m < materials; m++)
            for (int v = 0; v < MeshVoxelizer.VARIANTS; v++)
            {
                int index = 1 + m * MeshVoxelizer.VARIANTS + v;
                if (index < 256)
                    strength[index] = Strength((Material)m) * new float3(TOUGHER, TOUGHER, 1f);
            }

            // The skeleton's copies: the same group (no seam between a pier and the wall beside it), BEARING_PRESS and _BEND.
            var bearing = new float3(TOUGHER * BEARING_PRESS, TOUGHER * BEARING_BEND, 1f);
            for (int k = 0; k < BEARING_MATERIALS; k++)
            for (int v = 0; v < MeshVoxelizer.VARIANTS; v++)
                strength[BEARING_FIRST + k * MeshVoxelizer.VARIANTS + v] = Strength(BearingMaterial(k)) * bearing;

            return strength;
        }

        private void OnDrawGizmosSelected()
        {
            Gizmos.matrix = transform.localToWorldMatrix;
            Vector3 extent = (Vector3)_size * _voxelSize;
            Gizmos.DrawWireCube(new Vector3(0f, extent.y * 0.5f, 0f), extent);
        }

        [BurstCompile]
        private struct BuildVoxelsJob : IJob
        {
            public NativeArray<byte> Voxels;
            public int3 Size;
            public Shape Shape;
            public uint Seed;

            /// <summary>The tile's place in the world, in voxels, so the noise runs on across tiles.</summary>
            public int2 WorldOffset;

            /// <summary>Ground only: rise and fall with the terrain rather than fill the grid.</summary>
            public bool Terrain;
            public TerrainShape TerrainShape;
            [ReadOnly] public NativeArray<float4> Pads;
            [ReadOnly] public NativeArray<float4> Streets;
            public int StreetCount;
            public float RoadHalf;
            public float Verge;
            public float VoxelSize;

            /// <summary>World position of the min corner of voxel (0, 0, 0).</summary>
            public float3 WorldMin;

            public void Execute()
            {
                // A local, not a field: the job system insists every container field be assigned.
                NativeArray<int3> surface = Shape == Shape.Ground ? MeasureSurface() : default;

                for (int z = 0; z < Size.z; z++)
                for (int y = 0; y < Size.y; y++)
                for (int x = 0; x < Size.x; x++)
                {
                    int3 p = new int3(x, y, z);
                    int material = Shape switch
                    {
                        Shape.Wall => Wall(p),
                        Shape.Tower => Tower(p),
                        Shape.Ground => Ground(p, surface),
                        Shape.Tree => Tree(p),
                        Shape.Victorian => Victorian(p),
                        _ => House(p)
                    };

                    if (material >= 0)
                        Voxels[VoxelMath.Index(p, Size)] = Pick(material, p);
                }
            }

            /// <summary>What lies on top of a column of ground.</summary>
            private const int SOIL_MUD = (int)TerrainSoil.Mud;
            private const int SOIL_GRASS = (int)TerrainSoil.Grass;
            private const int SOIL_DRY_GRASS = (int)TerrainSoil.DryGrass;
            private const int SOIL_DIRT = (int)TerrainSoil.Dirt;
            private const int SOIL_ROCK = (int)TerrainSoil.Rock;

            /// <summary>How deep (voxels) the mud of a mud field goes: deep enough to wallow in.</summary>
            private const int MUD_DEPTH = 7;

            /// <summary>Voxels of earth under a skin of grass or mud before the rock begins (1.5 m).</summary>
            private const int EARTH_DEPTH = 15;

            /// <summary>
            /// One voxel of ground, by the column's soil and how deep below its surface it lies:
            /// grass over earth over rock; mud (dry, with wet patches) over earth; bare earth on
            /// steep slopes; rock on the steepest. Flat ground (no terrain) is all mud, as before.
            /// </summary>
            private int Ground(int3 p, NativeArray<int3> columns)
            {
                int3 column = columns[p.x + p.z * Size.x];
                int surface = column.x;
                if (p.y >= surface)
                    return -1;

                int depth = surface - 1 - p.y;
                int soil = column.y;

                if (!Terrain)
                {
                    if (depth >= 2)
                        return (int)Material.MudWet;
                    return Wet(p) ? (int)Material.MudWet : (int)Material.MudDry;
                }

                if (soil > SOIL_STREET)
                    return Street(soil - SOIL_STREET, column.z, depth);

                if (soil == SOIL_ROCK || depth >= EARTH_DEPTH)
                    return (int)Material.Rock;

                // Across the edge of a mud field the top two voxels are mixed: mud splashed on the
                // grass, tufts of grass in the mud, muddy grass between — a frayed edge, not a line.
                float mud = column.z / 255f;
                if (depth <= 1 && mud > 0.02f && mud < 0.98f && soil != SOIL_DIRT)
                {
                    float2 world = (new float2(p.x, p.z) + WorldOffset) * VoxelSize;
                    float clumps = noise.snoise(world * 0.9f) * 0.2f + noise.snoise(world * 2.7f + 5.3f) * 0.1f;
                    float scatter = (VoxelMath.Hash01(p, Seed + 303u) - 0.5f) * 0.3f;
                    float m = mud + clumps + scatter;

                    if (m > 0.56f)
                        return depth == 0 && !Wet(p) ? (int)Material.MudDry : (int)Material.MudWet;
                    if (m > 0.4f)
                        return depth == 0 ? (int)Material.MuddyGrass : (int)Material.Dirt;
                    if (soil == SOIL_MUD)
                        return depth == 0 ? GrassAt(p) : (int)Material.Dirt;
                }

                switch (soil)
                {
                    case SOIL_GRASS:
                        return depth == 0 ? GrassAt(p) : (int)Material.Dirt;
                    case SOIL_DRY_GRASS:
                        return depth == 0 ? (int)Material.DryGrass : (int)Material.Dirt;
                    case SOIL_MUD:
                        if (depth >= MUD_DEPTH)
                            return (int)Material.Dirt;
                        return depth == 0 && !Wet(p) ? (int)Material.MudDry : (int)Material.MudWet;
                    default:
                        return (int)Material.Dirt;
                }
            }

            /// <summary>Wet patches: where a slow noise, in world steps, rises high.</summary>
            private bool Wet(int3 p)
            {
                float2 at = new float2(p.x + WorldOffset.x, p.z + WorldOffset.y) * 0.035f;
                return noise.snoise(at) + 0.35f * noise.snoise(at * 3.1f) > 0.45f;
            }

            /// <summary>
            /// Per column: how many voxels tall the ground is (all of the grid when flat, else up to
            /// the terrain's height there) and what lies on top — by how high it is, how steep, and a
            /// patchy noise. One evaluation per column, not per voxel.
            /// </summary>
            private NativeArray<int3> MeasureSurface()
            {
                var columns = new NativeArray<int3>(Size.x * Size.z, Allocator.Temp);
                for (int z = 0; z < Size.z; z++)
                for (int x = 0; x < Size.x; x++)
                {
                    int top = Size.y;
                    int soil = SOIL_MUD;
                    int mud = 255;
                    if (Terrain)
                    {
                        float2 at = WorldMin.xz + (new float2(x, z) + 0.5f) * VoxelSize;
                        float height = VoxelTerrain.Height(at, TerrainShape, Pads);
                        float slope = VoxelTerrain.Slope(at, TerrainShape, Pads);
                        top = math.clamp((int)math.round((height - WorldMin.y) / VoxelSize), 1, Size.y);
                        soil = (int)VoxelTerrain.SoilFrom(at, height, slope, TerrainShape);
                        mud = (int)math.round(VoxelTerrain.MudAmount(at, height, slope, TerrainShape) * 255f);

                        int zone = VoxelTerrain.StreetZone(at, Streets.GetSubArray(0, StreetCount), RoadHalf, Verge,
                            out float along, out float across, out float distance);
                        if (zone != VoxelTerrain.STREET_NONE)
                        {
                            StreetColumn(zone, at, along / VoxelSize, across / VoxelSize, distance, ref top, ref soil, ref mud);
                            top = math.clamp(top, 1, Size.y);
                        }
                    }

                    // x — the top, y — the soil, z — how far into mud (0..255), for the edges; on a
                    // street z is the stone instead: its shade (bits 0-1) and whether it is a joint (bit 4).
                    columns[x + z * Size.x] = new int3(top, soil, mud);
                }

                return columns;
            }


            /// <summary>Lush, plain or pale grass, in patches with dithered borders.</summary>
            private int GrassAt(int3 p)
            {
                float2 at = (new float2(p.x, p.z) + WorldOffset) * VoxelSize;
                return VoxelTerrain.GrassTone(at, VoxelMath.Hash01(p, Seed + 101u)) switch
                {
                    -1 => (int)Material.GrassLush,
                    1 => (int)Material.GrassPale,
                    _ => (int)Material.Grass
                };
            }

            /// <summary>
            /// A tree standing in the middle of its grid: a trunk with a flared foot and a slight
            /// lean, and on it either a lumpy leafy crown (even seeds) or a pine's tiered cone of
            /// needles (odd seeds). The crown overlaps the trunk, so it all hangs together until a
            /// ram or a shell cuts the trunk.
            /// </summary>
            private int Tree(int3 p)
            {
                bool pine = (Seed & 1u) == 1u;
                float3 at = (float3)p + 0.5f;
                float cx = Size.x * 0.5f;
                float cz = Size.z * 0.5f;
                float h = Size.y;

                // A slight lean, the same way all up the trunk, growing toward the top.
                float lean = (VoxelMath.Hash01(new int3(7, 7, 7), Seed) - 0.5f) * Size.x * 0.12f;
                float leanZ = (VoxelMath.Hash01(new int3(9, 9, 9), Seed) - 0.5f) * Size.z * 0.12f;
                float rise = at.y / h;
                float tx = cx + lean * rise * rise;
                float tz = cz + leanZ * rise * rise;

                // A pine's trunk stops well inside its cone, so no bare pole sticks out of the top.
                float trunkTop = h * (pine ? 0.75f : 0.6f);
                if (at.y < trunkTop)
                {
                    float radius = math.lerp(2.6f, 1.4f, at.y / trunkTop);
                    if (at.y < 3f)
                        radius += 1.6f * (1f - at.y / 3f);
                    float2 d = at.xz - new float2(tx, tz);
                    if (math.lengthsq(d) <= radius * radius)
                        return (int)Material.Bark;
                }

                float lump = noise.snoise(at * 0.16f + Seed * 0.37f);
                return pine ? Needles(at, tx, tz, h, lump) : Crown(at, tx, tz, h, lump);
            }

            private int Crown(float3 at, float tx, float tz, float h, float lump)
            {
                float3 centre = new float3(tx, h * 0.68f, tz);
                float3 radii = new float3(Size.x * 0.46f, h * 0.29f, Size.z * 0.46f);
                float3 q = (at - centre) / radii;
                float reach = 1f + 0.28f * lump;
                if (math.lengthsq(q) > reach * reach)
                    return -1;

                // Darker underneath and in the hollows, lighter on top.
                float shade = noise.snoise(at * 0.3f + 11.1f) + (at.y - centre.y) / radii.y * 0.6f;
                return shade < -0.15f ? (int)Material.LeavesDark : (int)Material.Leaves;
            }

            private int Needles(float3 at, float tx, float tz, float h, float lump)
            {
                float bottom = h * 0.2f;
                if (at.y < bottom)
                    return -1;

                float t = (at.y - bottom) / (h - bottom);
                // Tiers: each a skirt that flares out at its foot and narrows up to the next.
                float tier = math.frac((at.y - bottom) / 9f);
                float radius = Size.x * 0.46f * (1f - t) * (1f - 0.38f * tier) * (1f + 0.15f * lump);
                float2 d = at.xz - new float2(tx, tz);
                if (math.lengthsq(d) > radius * radius)
                    return -1;
                return tier > 0.7f ? (int)Material.LeavesDark : (int)Material.Needles;
            }

            // ---------------------------------------------------------------- streets

            /// <summary>Soil codes above this are street zones (road, kerb).</summary>
            private const int SOIL_STREET = 10;

            /// <summary>Street stone flags, beside its shade (bits 0-1).</summary>
            private const int STONE_JOINT = 16;
            private const int STONE_MISSING = 32;
            private const int STONE_POTHOLE = 64;
            private const int STONE_GRASS = 128;

            private static int Mod(int v, int m) => (v % m + m) % m;

            /// <summary>
            /// A column of street. The road is a worn, live thing: cobbles laid unevenly, some sunk,
            /// some gone (more of them towards the edges), potholes holding mud. The kerb is neat
            /// granite with the odd stone missing. Beyond it the verge frays into the ground round
            /// it: stray cobbles and bare earth, thinning out with distance, in blotches.
            /// </summary>
            private void StreetColumn(int zone, float2 at, float along, float across, float distance,
                ref int top, ref int soil, ref int stone)
            {
                int3 spot = new int3((int)math.floor(at.x / VoxelSize), 0, (int)math.floor(at.y / VoxelSize));
                float chance = VoxelMath.Hash01(spot, Seed + 51u);

                if (zone == VoxelTerrain.STREET_VERGE)
                {
                    float t = (distance - RoadHalf - VoxelTerrain.KERB) / math.max(0.01f, Verge);
                    float blot = noise.snoise(at * 0.8f) * 0.25f + noise.snoise(at * 2.3f + 4.1f) * 0.12f;
                    float r = chance * 0.5f + blot;
                    if (r > t * 0.9f + 0.4f)
                    {
                        // A cobble that has worked loose and lies in the grass.
                        soil = SOIL_STREET + VoxelTerrain.STREET_ROAD;
                        stone = (int)(chance * 4f) & 3;
                    }
                    else if (r > t * 0.8f + 0.12f)
                    {
                        soil = SOIL_DIRT;
                    }

                    return;
                }

                if (zone == VoxelTerrain.STREET_KERB)
                {
                    int kerbStone = (int)math.floor(along / 8f);
                    // Where the road has broken up, the kerb has mostly gone with it.
                    float wearHere = noise.snoise(at * 0.06f + 21.3f) * 0.7f + noise.snoise(at * 0.19f - 5.2f) * 0.3f;
                    float lost = 0.1f + math.smoothstep(0.02f, 0.42f, wearHere) * 0.7f;
                    if (VoxelMath.Hash01(new int3(kerbStone, 0, 77), Seed) < lost)
                    {
                        // A kerb stone gone: a gap of bare earth at road level.
                        soil = SOIL_STREET + VoxelTerrain.STREET_ROAD;
                        stone = STONE_MISSING;
                        top -= 1;
                        return;
                    }

                    soil = SOIL_STREET + VoxelTerrain.STREET_KERB;
                    stone = Paving(zone, along, across, out _, out _);
                    top += 1;
                    return;
                }

                soil = SOIL_STREET + VoxelTerrain.STREET_ROAD;
                stone = Paving(zone, along, across, out bool joint, out int2 id);
                float stoneChance = VoxelMath.Hash01(new int3(id, 9), Seed);
                float edge = math.saturate((distance / math.max(0.01f, RoadHalf) - 0.65f) / 0.35f);

                // The road is not the same all along: stretches of 10–20 m are kept up, worn, or all
                // but gone to mud.
                float wear = noise.snoise(at * 0.06f + 21.3f) * 0.7f + noise.snoise(at * 0.19f - 5.2f) * 0.3f;
                float broken = math.smoothstep(0.02f, 0.42f, wear);
                float kept = math.smoothstep(-0.25f, -0.6f, wear);

                // Grass creeps in from the edges, in patches: into the joints, into the gaps.
                float creep = edge + noise.snoise(at * 0.35f + 8.8f) * 0.5f + broken * 0.35f - kept * 0.3f;
                bool grassy = creep > 0.6f;

                // Different stone in different stretches (repairs, another quarry), and the odd
                // stone of another tone among them.
                int tone = Tone(at, id);
                stone |= tone << 8;

                // Potholes: a slow noise, a voxel to three deep, with mud standing in them;
                // many more where the road has broken up.
                float hole = noise.snoise(at * 0.45f + 3.7f) * 0.7f + noise.snoise(at * 1.3f - 1.1f) * 0.3f;
                if (hole > 0.6f - broken * 0.45f && kept < 0.5f)
                {
                    top -= math.min(3, 1 + (int)((hole - 0.6f + broken * 0.45f) * 10f));
                    stone = STONE_POTHOLE | (stone & 3);
                    return;
                }

                // Cobbles gone: more towards the edges, most of them where the road has broken up
                // (mud there), hardly any where it is kept.
                if (stoneChance < (0.04f + edge * 0.4f) * (1f - kept * 0.8f) + broken * 0.75f)
                {
                    top -= 1;
                    stone = (grassy ? STONE_GRASS : broken > 0.4f ? STONE_POTHOLE : STONE_MISSING) | (stone & 3);
                    return;
                }

                // Joints lie a voxel down, mossed over near a grassy edge; so does the odd sunken cobble.
                if (joint && grassy)
                    stone |= STONE_GRASS;
                if (joint || stoneChance > 0.88f - broken * 0.2f)
                    top -= 1;
            }

            /// <summary>
            /// Which stone a cobble is: 0 the common grey, 1 a warm brownish stone, 2 a dark one —
            /// by stretch of road, with one stone in seven of another tone.
            /// </summary>
            private int Tone(float2 at, int2 id)
            {
                float stretch = noise.snoise(at * 0.08f + 11.7f);
                int tone = stretch > 0.3f ? 1 : stretch < -0.35f ? 2 : 0;
                float odd = VoxelMath.Hash01(new int3(id, 13), Seed);
                if (odd < 0.14f)
                    tone = (tone + 1 + (int)(odd * 14f)) % 3;
                return tone;
            }

            /// <summary>
            /// The stone a street column belongs to: cobbles in courses of their own length and
            /// offset, now and then a stone spanning two courses; kerb stones 80 cm long. Returns
            /// the stone's shade (0..3), with <see cref="STONE_JOINT"/> for a joint.
            /// </summary>
            private int Paving(int zone, float along, float across, out bool joint, out int2 stone)
            {
                int a = (int)math.floor(along);
                int b = (int)math.floor(across);

                if (zone == VoxelTerrain.STREET_ROAD)
                {
                    int course = (int)math.floor(across / 3f);
                    int length = 3 + (int)(VoxelMath.Hash01(new int3(course, 0, 1), Seed) * 3f);
                    int offset = (int)(VoxelMath.Hash01(new int3(course, 0, 2), Seed) * length);
                    int shifted = a + offset;
                    int index = (int)math.floor(shifted / (float)length);
                    bool spans = VoxelMath.Hash01(new int3(course, index, 3), Seed) < 0.2f;
                    joint = Mod(shifted, length) == 0 || (Mod(b, 3) == 0 && !spans);
                    stone = new int2(index, course);
                }
                else
                {
                    joint = Mod(a, 8) == 0;
                    stone = new int2((int)math.floor(a / 8f), 0);
                }

                int shade = (int)(VoxelMath.Hash01(new int3(stone, zone), Seed) * 4f) & 3;
                return shade | (joint ? STONE_JOINT : 0);
            }

            /// <summary>A street voxel: the stone on top (its own shade), its bed beneath.</summary>
            private int Street(int zone, int stone, int depth)
            {
                int shade = (stone & 3) + 1;
                int tone = (stone >> 8) & 3;

                if (depth == 0)
                {
                    if ((stone & STONE_GRASS) != 0)
                        return (int)Material.Grass;
                    if ((stone & STONE_POTHOLE) != 0)
                        return (stone & 1) == 0 ? (int)Material.MudWet : (int)Material.MudDry;
                    if ((stone & STONE_MISSING) != 0)
                        return (int)Material.Dirt;
                    if ((stone & STONE_JOINT) != 0)
                        return (int)Material.Joint;
                    if (zone == VoxelTerrain.STREET_KERB)
                        return (int)Material.Kerb | (shade << 8);
                    int cobble = tone == 1 ? (int)Material.CobbleWarm : tone == 2 ? (int)Material.CobbleDark : (int)Material.Cobble;
                    return cobble | (shade << 8);
                }

                // Kerb stones stand deep; the rest lie on a bed of earth.
                if (zone == VoxelTerrain.STREET_KERB && depth <= 2)
                    return (int)Material.Kerb | (shade << 8);
                if ((stone & STONE_POTHOLE) != 0 && depth == 1)
                    return (int)Material.MudWet;
                return depth >= EARTH_DEPTH ? (int)Material.Rock : (int)Material.Dirt;
            }

            // ---------------------------------------------------------------- village house

            private const int V_SIDE = 3;
            private const int V_FRONT = 6;
            private const int V_BACK = 3;
            private const int V_PLINTH = 5;
            private const int V_FLOOR = 28;
            private const int V_CORNICE = 3;

            /// <summary>Nothing here.</summary>
            private const int EMPTY = -1;

            /// <summary>No opening here: plain wall.</summary>
            private const int WALL = -2;

            private int Floors => math.clamp((Size.y - 50) / V_FLOOR, 1, 3);

            private int WallMaterial => (int)(Seed % 3u) switch
            {
                0 => (int)Material.BrickRed,
                1 => (int)Material.BrickYellow,
                _ => (int)Material.Stucco
            };

            private bool HasBay => (Seed / 3u) % 3u == 0u;
            private int BayColumn => (Seed / 7u) % 2u == 0u ? 0 : 2;

            private static int StoreyBase(int storey) => V_PLINTH + storey * V_FLOOR;
            private static int Sill(int storey) => StoreyBase(storey) + (storey == 0 ? 6 : 7);
            private static int Head(int storey) => StoreyBase(storey) + (storey == 0 ? 23 : 22);
            private const int WINDOW_HALF = 3;
            private const int DOOR_HALF = 4;
            private static int DoorTop => V_PLINTH + 20;

            // ---------------------------------------------------------------- skeleton

            /// <summary>Marks a voxel load-bearing (nothing for EMPTY).</summary>
            private static int Bear(int material) => material >= 0 ? material | BEARING : material;

            /// <summary>Height (voxels) of a ring beam: the course a floor rests on, and the top of the wall.</summary>
            private const int BEAM = 4;

            /// <summary>Width (voxels) of a pier between windows, and of a corner.</summary>
            private const int PIER = 5;

            /// <summary>How far (voxels) in from the wall a floor's edge bears.</summary>
            private const int FLOOR_EDGE = 4;

            /// <summary>
            /// Whether a town house's wall voxel is in its skeleton: a beam at every upper floor and
            /// under the eaves, the corners, the piers midway between the windows of the front and
            /// back, and on the sides the pier under each chimney stack. Not the plinth: it stands on
            /// the ground, and a crater under a corner must still take it (user, 2026-11-17).
            /// </summary>
            private static bool VictorianBearing(bool side, int u, int length, int z, int z0, int z1, int y, int wallTop)
            {
                if (y < V_PLINTH)
                    return false;
                if (y >= wallTop - BEAM || (y >= V_PLINTH + V_FLOOR && (y - V_PLINTH) % V_FLOOR < BEAM))
                    return true;
                if (u < PIER - 1 || u >= length - (PIER - 1))
                    return true;
                if (side)
                {
                    int chimney = ChimneyZ(z0, z1);
                    return z >= chimney && z < chimney + CHIMNEY_DEPTH;
                }

                // Three bays: the piers stand at a third and two thirds of the front.
                for (int k = 1; k < 3; k++)
                    if (math.abs(u - length * k / 3) <= PIER / 2)
                        return true;
                return false;
            }

            /// <summary>The first z of a chimney stack (Roof), and how deep it is.</summary>
            private static int ChimneyZ(int z0, int z1) => (int)((z0 + z1) * 0.5f) - 4;

            private const int CHIMNEY_DEPTH = 6;

            /// <summary>
            /// A village house of about 1900, its walls within the grid: 3 voxels left at the sides
            /// and back for the trim and eaves to jut into, 6 at the front for the steps and bay.
            /// </summary>
            private int Victorian(int3 p)
            {
                int x0 = V_SIDE, x1 = Size.x - V_SIDE, z0 = V_FRONT, z1 = Size.z - V_BACK;
                int floors = Floors;
                int wallTop = V_PLINTH + floors * V_FLOOR;
                int eaves = wallTop + V_CORNICE;

                if (p.y >= eaves)
                    return Roof(p, x0, x1, z0, z1, eaves);

                bool inX = p.x >= x0 && p.x < x1;
                bool inZ = p.z >= z0 && p.z < z1;

                if (inX && inZ)
                {
                    int dF = p.z - z0, dB = z1 - 1 - p.z, dL = p.x - x0, dR = x1 - 1 - p.x;
                    int d = math.min(math.min(dF, dB), math.min(dL, dR));
                    if (d >= 2)
                    {
                        // Every upper floor's edge along the walls bears.
                        int inside = Interior(p, x0, x1, z0, z1, floors, wallTop);
                        bool floor = p.y > V_PLINTH && ((p.y - V_PLINTH) % V_FLOOR == 0 || p.y == wallTop);
                        return floor && d < 2 + FLOOR_EDGE ? Bear(inside) : inside;
                    }

                    bool side = d != dF && d != dB;
                    int u = side ? p.z - z0 : p.x - x0;
                    int length = side ? z1 - z0 : x1 - x0;
                    int face = d == dF ? 0 : d == dB ? 1 : d == dL ? 2 : 3;
                    int wall = Facade(face, u, length, p.y, d, wallTop);
                    return VictorianBearing(side, u, length, p.z, z0, z1, p.y, wallTop) ? Bear(wall) : wall;
                }

                if (inX && p.z < z0)
                {
                    int front = FrontExtras(p, x0, x1, z0);
                    if (front != EMPTY)
                        return front;
                }

                int outF = z0 - p.z, outB = p.z - (z1 - 1), outL = x0 - p.x, outR = p.x - (x1 - 1);
                if (inX && outF is 1 or 2)
                    return Jut(0, p.x - x0, x1 - x0, p.y, outF, wallTop);
                if (inX && outB is 1 or 2)
                    return Jut(1, p.x - x0, x1 - x0, p.y, outB, wallTop);
                if (inZ && outL is 1 or 2)
                    return Jut(2, p.z - z0, z1 - z0, p.y, outL, wallTop);
                if (inZ && outR is 1 or 2)
                    return Jut(3, p.z - z0, z1 - z0, p.y, outR, wallTop);
                return EMPTY;
            }

            /// <summary>
            /// One voxel of an outer wall two voxels thick (<paramref name="layer"/> 0 — outside,
            /// 1 — inside) on face 0 front, 1 back, 2 left, 3 right; <paramref name="u"/> runs
            /// along it. Inside, the wall is papered over a dark wooden dado.
            /// </summary>
            private int Facade(int face, int u, int length, int y, int layer, int wallTop)
            {
                if (y < V_PLINTH)
                    return (int)Material.Stone;
                if (y >= wallTop)
                    return (int)Material.Trim;

                int storey = (y - V_PLINTH) / V_FLOOR;
                int rel = (y - V_PLINTH) % V_FLOOR;

                if (layer == 0 && storey >= 1 && rel == 0)
                    return (int)Material.Trim;

                int opening = Opening(face, u, length, y, storey, layer);
                if (opening != WALL)
                    return opening;

                if (layer == 1)
                {
                    int room = face == 2 ? 0 : face == 3 ? 1 : u < length / 2 ? 0 : 1;
                    return InnerWall(storey, room, rel);
                }

                // Quoins: long and short stones in turn up every corner.
                int reach = (y - V_PLINTH) / 4 % 2 == 0 ? 4 : 2;
                if (u < reach || u >= length - reach)
                    return (int)Material.Trim;

                return WallMaterial;
            }

            /// <summary>Wallpaper over a wooden dado with a rail; a pattern of its own per room.</summary>
            private int InnerWall(int storey, int room, int rel)
            {
                if (rel <= 7)
                    return (int)Material.Panel;
                if (rel == 8)
                    return (int)Material.Furniture;
                return (int)((storey * 2 + room + (int)(Seed % 3u)) % 3) switch
                {
                    0 => (int)Material.Wallpaper1,
                    1 => (int)Material.Wallpaper2,
                    _ => (int)Material.Wallpaper3
                };
            }

            /// <summary>Window and door openings: three bays to the front and back, two to the sides.</summary>
            private int Opening(int face, int u, int length, int y, int storey, int layer)
            {
                int count = face <= 1 ? 3 : 2;
                for (int k = 0; k < count; k++)
                {
                    int c = length * (2 * k + 1) / (2 * count);
                    int du = math.abs(u - c);

                    if (face == 0 && storey == 0 && k == 1)
                    {
                        // The front door: panelled, with a glazed fanlight over it.
                        if (du <= DOOR_HALF && y >= V_PLINTH && y < DoorTop + 3)
                        {
                            if (layer == 0)
                                return EMPTY;
                            if (y >= DoorTop)
                                return du == DOOR_HALF || y == DoorTop + 2 || du == 0 ? (int)Material.Frame : (int)Material.Glass;
                            return du == DOOR_HALF || y == DoorTop - 1 || (du == 2 && y > V_PLINTH + 3) ? (int)Material.Frame : (int)Material.Door;
                        }

                        continue;
                    }

                    if (face == 0 && storey == 0 && HasBay && k == BayColumn)
                    {
                        if (du <= 6 && y >= V_PLINTH && y < V_PLINTH + V_FLOOR - 5)
                            return EMPTY;
                        continue;
                    }

                    // A sash window: set back in the wall, a dull white frame with glazing bars.
                    int sill = Sill(storey), top = Head(storey);
                    if (du <= WINDOW_HALF && y >= sill && y < top)
                    {
                        if (layer == 0)
                            return EMPTY;
                        bool bar = du == WINDOW_HALF || y == sill || y == top - 1 || du == 0 || y == (sill + top) / 2;
                        return bar ? (int)Material.Frame : (int)Material.Glass;
                    }

                    if (layer == 0 && du <= WINDOW_HALF + 1 && (y == sill - 1 || (y >= top && y < top + 2)))
                        return (int)Material.Trim;
                }

                return WALL;
            }

            /// <summary>Trim jutting one or two voxels (<paramref name="out"/>) out of a face.</summary>
            private int Jut(int face, int u, int length, int y, int @out, int wallTop)
            {
                if (y < V_PLINTH)
                    return EMPTY;

                if (y >= wallTop)
                {
                    int row = y - wallTop;
                    if (@out == 1)
                        return row == 0 && u % 2 == 1 ? EMPTY : (int)Material.Trim;
                    return row == V_CORNICE - 1 ? (int)Material.Trim : EMPTY;
                }

                if (@out != 1)
                    return EMPTY;

                int storey = (y - V_PLINTH) / V_FLOOR;
                if (storey >= 1 && (y - V_PLINTH) % V_FLOOR == 0)
                    return (int)Material.Trim;

                int count = face <= 1 ? 3 : 2;
                for (int k = 0; k < count; k++)
                {
                    int c = length * (2 * k + 1) / (2 * count);
                    int du = math.abs(u - c);

                    if (face == 0 && storey == 0 && k == 1)
                    {
                        int pediment = DoorTop + 4;
                        if (y >= pediment && y < pediment + 3 && du <= 6 - (y - pediment) * 2)
                            return (int)Material.Trim;
                        continue;
                    }

                    if (face == 0 && storey == 0 && HasBay && k == BayColumn)
                        continue;

                    if (du <= WINDOW_HALF + 1 && (y == Sill(storey) - 1 || y == Head(storey) + 1))
                        return (int)Material.Trim;
                }

                return EMPTY;
            }

            /// <summary>In front: stone steps up to the door, and (some houses) a bay window.</summary>
            private int FrontExtras(int3 p, int x0, int x1, int z0)
            {
                int u = p.x - x0;
                int length = x1 - x0;
                int d = z0 - p.z;

                int door = length * 3 / 6;
                if (math.abs(u - door) <= 5 && d <= 4 && p.y < V_PLINTH - d + 1)
                    return (int)Material.Stone;

                if (!HasBay)
                    return EMPTY;

                const int depth = 4;
                const int half = 7;
                int bay = length * (2 * BayColumn + 1) / 6;
                int du = math.abs(u - bay);
                int reach = half - math.max(0, d - 2);
                int top = V_PLINTH + V_FLOOR - 5;

                if (d <= depth && du <= reach)
                {
                    if (p.y < V_PLINTH)
                        return (int)Material.Stone;
                    if (p.y < top)
                    {
                        bool shell = d == depth || du == reach;
                        if (!shell)
                            return EMPTY;
                        int sill = V_PLINTH + 6, head = top - 3;
                        if (p.y >= sill && p.y < head)
                            return du % 4 == 0 || p.y == sill || p.y == head - 1 ? (int)Material.Frame : (int)Material.Glass;
                        return p.y == sill - 1 || p.y >= head ? (int)Material.Trim : WallMaterial;
                    }
                }

                int lift = p.y - top;
                if (lift >= 0 && lift < depth && d <= depth - lift && du <= half - math.max(0, d - 2) + 1)
                    return (int)Material.Slate;

                return EMPTY;
            }

            // ---------------------------------------------------------------- rooms

            private static bool In(int v, int lo, int hi) => v >= lo && v < hi;

            /// <summary>
            /// Inside the house: a foundation, a wooden floor at every storey, a partition with a
            /// doorway splitting each storey into two rooms, a staircase up along the back wall of
            /// the right-hand room, and the rooms furnished — a parlour and a kitchen below,
            /// bedrooms above.
            /// </summary>
            private int Interior(int3 p, int x0, int x1, int z0, int z1, int floors, int wallTop)
            {
                if (p.y < V_PLINTH)
                    return (int)Material.Stone;
                if (p.y > wallTop)
                    return EMPTY;

                int storey = (p.y - V_PLINTH) / V_FLOOR;
                int rel = (p.y - V_PLINTH) % V_FLOOR;
                int ix0 = x0 + 2, ix1 = x1 - 2, iz0 = z0 + 2, iz1 = z1 - 2;
                int xm = (ix0 + ix1) / 2;

                // The stairs: up along the back wall of the right-hand room, to the storey above.
                int sx0 = xm + 1, sx1 = ix1, sz0 = iz1 - 6;
                bool stairBand = In(p.x, sx0, sx1) && In(p.z, sz0, iz1);

                if (rel == 0)
                {
                    // A hole in the floor where the stairs come up.
                    if (storey >= 1 && storey < floors + 1 && stairBand && p.x >= sx0 + 8 && p.y < wallTop)
                        return EMPTY;
                    return Rug(p, storey, ix0, xm, iz0) ? (int)Material.Carpet : (int)Material.FloorWood;
                }

                if (p.y == wallTop)
                    return (int)Material.FloorWood;

                if (storey < floors - 1 && stairBand)
                {
                    int step = (int)math.ceil((p.x - sx0 + 1) * (float)V_FLOOR / (sx1 - sx0));
                    if (rel < step)
                        return (int)Material.Panel;
                    if (rel == step)
                        return (int)Material.FloorWood;
                }

                // The partition, with a doorway near the front.
                if (p.x == xm)
                {
                    if (In(p.z, iz0 + 4, iz0 + 11) && rel <= 20)
                        return EMPTY;
                    return InnerWall(storey, 0, rel);
                }

                return storey == 0
                    ? (p.x < xm ? Parlour(p, rel, ix0, xm, iz0, iz1) : Kitchen(p, rel, xm, ix1, iz0))
                    : (p.x < xm ? Bedroom(p, rel, ix0, xm, iz0, iz1) : Study(p, rel, xm, ix1, iz0));
            }

            private static bool Rug(int3 p, int storey, int ix0, int xm, int iz0) =>
                storey == 0
                    ? In(p.x, ix0 + 7, xm - 6) && In(p.z, iz0 + 10, iz0 + 30)
                    : In(p.x, ix0 + 4, xm - 9) && In(p.z, iz0 + 4, iz0 + 12);

            /// <summary>A table: a top at the given height on four corner legs.</summary>
            private static bool Table(int3 p, int rel, int xa, int xb, int za, int zb, int height) =>
                In(p.x, xa, xb) && In(p.z, za, zb) &&
                (rel == height || (rel < height && (p.x == xa || p.x == xb - 1) && (p.z == za || p.z == zb - 1)));

            /// <summary>A chair: a seat on legs, its back along the given side (0 -x, 1 +x, 2 -z, 3 +z).</summary>
            private static bool Chair(int3 p, int rel, int xa, int za, int back)
            {
                int xb = xa + 4, zb = za + 4;
                if (!In(p.x, xa, xb) || !In(p.z, za, zb))
                    return false;
                if (rel == 4)
                    return true;
                if (rel < 4)
                    return (p.x == xa || p.x == xb - 1) && (p.z == za || p.z == zb - 1);
                bool onBack = back switch { 0 => p.x == xa, 1 => p.x == xb - 1, 2 => p.z == za, _ => p.z == zb - 1 };
                return onBack && rel <= 10;
            }

            private int Parlour(int3 p, int rel, int ix0, int xm, int iz0, int iz1)
            {
                int zc = (iz0 + iz1) / 2;

                // A fireplace on the gable wall: stone surround, black grate, a wooden mantel.
                if (In(p.x, ix0, ix0 + 3) && In(p.z, zc - 5, zc + 5) && rel <= 13)
                    return In(p.x, ix0, ix0 + 2) && In(p.z, zc - 3, zc + 3) && rel <= 7 ? (int)Material.Iron : (int)Material.Stone;
                if (In(p.x, ix0, ix0 + 4) && In(p.z, zc - 6, zc + 6) && rel is 14 or 15)
                    return (int)Material.Furniture;

                // A table with two chairs on the rug.
                if (Table(p, rel, ix0 + 10, ix0 + 18, zc - 4, zc + 4, 7))
                    return (int)Material.Furniture;
                if (Chair(p, rel, ix0 + 10, zc - 9, 2) || Chair(p, rel, ix0 + 14, zc + 5, 3))
                    return (int)Material.Furniture;

                // An armchair by the fire.
                if (In(p.x, ix0 + 4, ix0 + 10) && In(p.z, zc + 9, zc + 15) && rel <= 9)
                {
                    bool seat = rel <= 4;
                    bool back = p.z >= zc + 13;
                    bool arm = (p.x == ix0 + 4 || p.x == ix0 + 9) && rel <= 6;
                    if (seat || back || arm)
                        return (int)Material.Fabric;
                }

                // A bookcase against the partition, its shelves full.
                if (In(p.x, xm - 4, xm) && In(p.z, iz1 - 12, iz1 - 2) && rel <= 20)
                {
                    if (p.x == xm - 4 && rel % 5 != 0)
                        return (p.z % 3) switch { 0 => (int)Material.Fabric, 1 => (int)Material.Linen, _ => (int)Material.Carpet };
                    return (int)Material.Furniture;
                }

                return EMPTY;
            }

            private int Kitchen(int3 p, int rel, int xm, int ix1, int iz0)
            {
                // The black iron range against the gable, its flue up to the ceiling.
                if (In(p.x, ix1 - 4, ix1) && In(p.z, iz0 + 4, iz0 + 12) && rel <= 9)
                    return (int)Material.Iron;
                if (In(p.x, ix1 - 3, ix1 - 1) && In(p.z, iz0 + 7, iz0 + 9))
                    return (int)Material.Iron;

                // A scrubbed table and two chairs.
                if (Table(p, rel, xm + 8, xm + 16, iz0 + 14, iz0 + 22, 7))
                    return (int)Material.Furniture;
                if (Chair(p, rel, xm + 9, iz0 + 9, 2) || Chair(p, rel, xm + 11, iz0 + 23, 3))
                    return (int)Material.Furniture;

                // A dresser against the partition with a row of plates.
                if (In(p.x, xm + 1, xm + 5) && In(p.z, iz0 + 2, iz0 + 12) && rel <= 18)
                    return p.x == xm + 4 && In(rel, 11, 17) && p.z % 2 == 0 ? (int)Material.Linen : (int)Material.Furniture;

                return EMPTY;
            }

            private int Bedroom(int3 p, int rel, int ix0, int xm, int iz0, int iz1)
            {
                int zc = (iz0 + iz1) / 2;

                // A double bed, its head to the gable wall.
                if (In(p.z, zc - 7, zc + 7))
                {
                    if (In(p.x, ix0, ix0 + 2) && rel <= 10)
                        return (int)Material.Furniture;
                    if (In(p.x, ix0, ix0 + 20))
                    {
                        if (rel <= 3)
                            return (int)Material.Furniture;
                        if (rel == 4)
                            return (int)Material.Linen;
                        if (rel == 5)
                            return In(p.x, ix0 + 2, ix0 + 6) && In(p.z, zc - 5, zc + 5) ? (int)Material.Linen : p.x >= ix0 + 7 ? (int)Material.Fabric : EMPTY;
                        if (rel == 6 && In(p.x, ix0 + 2, ix0 + 6) && In(p.z, zc - 5, zc + 5))
                            return (int)Material.Linen;
                    }
                }

                // A tall wardrobe against the partition.
                if (In(p.x, xm - 6, xm) && In(p.z, iz1 - 11, iz1 - 2) && rel <= 22)
                    return p.x == xm - 6 && p.z == iz1 - 7 && rel > 2 ? (int)Material.Panel : (int)Material.Furniture;

                return EMPTY;
            }

            private int Study(int3 p, int rel, int xm, int ix1, int iz0)
            {
                // A writing desk under the window, drawers to one side, and its chair.
                if (Table(p, rel, ix1 - 6, ix1, iz0 + 4, iz0 + 14, 7))
                    return (int)Material.Furniture;
                if (In(p.x, ix1 - 6, ix1) && In(p.z, iz0 + 4, iz0 + 7) && rel < 7)
                    return (int)Material.Furniture;
                if (Chair(p, rel, ix1 - 10, iz0 + 7, 0))
                    return (int)Material.Furniture;

                // A narrow bed along the partition.
                if (In(p.z, iz0 + 20, iz0 + 29) && In(p.x, xm + 1, xm + 19))
                {
                    if (p.x <= xm + 2 && rel <= 8)
                        return (int)Material.Furniture;
                    if (rel <= 3)
                        return (int)Material.Furniture;
                    if (rel == 4)
                        return (int)Material.Linen;
                    if (rel == 5)
                        return p.x <= xm + 6 ? (int)Material.Linen : (int)Material.Fabric;
                }

                return EMPTY;
            }

            /// <summary>
            /// The slate gable roof, its ridge along the front, overhanging two voxels all round; the
            /// gable ends with a round attic window; a chimney stack on each gable.
            /// </summary>
            private int Roof(int3 p, int x0, int x1, int z0, int z1, int eaves)
            {
                float zc = (z0 + z1) * 0.5f;
                float half = (z1 - z0) * 0.5f + 2f;
                float top = eaves + half - math.abs(p.z + 0.5f - zc);
                int ridge = (int)(eaves + half);

                // The chimney stacks stand on the side piers (VictorianBearing): they bear, and stand when the roof goes.
                int cz0 = ChimneyZ(z0, z1), cz1 = cz0 + CHIMNEY_DEPTH, chimneyTop = ridge + 8;
                bool left = p.x >= x0 + 1 && p.x < x0 + 7;
                bool right = p.x >= x1 - 7 && p.x < x1 - 1;
                if ((left || right) && p.z >= cz0 && p.z < cz1 && p.y < chimneyTop)
                    return Bear(WallMaterial == (int)Material.Stucco ? (int)Material.BrickRed : WallMaterial);
                bool capLeft = p.x >= x0 && p.x < x0 + 8;
                bool capRight = p.x >= x1 - 8 && p.x < x1;
                if ((capLeft || capRight) && p.z >= cz0 - 1 && p.z < cz1 + 1 && p.y >= chimneyTop && p.y < chimneyTop + 2)
                    return Bear((int)Material.Trim);
                if (p.y >= chimneyTop + 2 && p.y < chimneyTop + 5 && p.z >= cz0 + 2 && p.z < cz0 + 4)
                {
                    int lx = capLeft ? p.x - (x0 + 1) : p.x - (x1 - 7);
                    if ((capLeft || capRight) && (lx is 1 or 2 || lx is 4 or 5))
                        return (int)Material.Pot;
                }

                if (p.x < x0 - 2 || p.x >= x1 + 2 || p.z < z0 - 2 || p.z >= z1 + 2)
                    return EMPTY;

                if ((p.x == x0 - 2 || p.x == x1 + 1) && p.y < top && p.y >= top - 3)
                    return (int)Material.Trim;

                if (p.y < top && p.y >= top - 2.5f)
                    return (int)Material.Slate;

                bool gable = (p.x >= x0 && p.x < x0 + 2) || (p.x >= x1 - 2 && p.x < x1);
                if (gable && p.z >= z0 && p.z < z1 && p.y < top - 2)
                {
                    float2 w = new float2(p.z + 0.5f - zc, p.y + 0.5f - (eaves + 8f));
                    float r2 = math.lengthsq(w);
                    if (r2 < 12f)
                    {
                        bool outer = p.x == x0 || p.x == x1 - 1;
                        if (outer)
                            return EMPTY;
                        return r2 > 6f || math.abs(w.x) < 0.6f || math.abs(w.y) < 0.6f ? (int)Material.Frame : (int)Material.Glass;
                    }

                    int gableWall = r2 < 20f && (p.x == x0 || p.x == x1 - 1) ? (int)Material.Trim : WallMaterial;
                    return p.z >= cz0 && p.z < cz1 ? Bear(gableWall) : gableWall;
                }

                if (p.y == eaves && p.x >= x0 && p.x < x1 && p.z >= z0 && p.z < z1)
                    return (int)Material.FloorWood;

                return EMPTY;
            }

            /// <summary>A free-standing brick wall on a concrete footing, along X.</summary>
            private int Wall(int3 p)
            {
                if (p.y < 2)
                    return (int)Material.Concrete;
                if (p.y >= Size.y - 2)
                    return (int)Material.Concrete;
                return (int)Material.Brick;
            }

            /// <summary>
            /// Two storeys: a slab floor, brick walls two voxels thick, a door, rows of windows,
            /// a concrete floor between the storeys and a flat roof with a parapet.
            /// </summary>
            private int House(int3 p)
            {
                const int wall = 2;
                int3 s = Size;
                int middle = s.y / 2;
                int roof = s.y - 4;

                if (p.y == 0)
                    return (int)Material.Concrete;

                bool shell = p.x < wall || p.x >= s.x - wall || p.z < wall || p.z >= s.z - wall;

                if (p.y >= roof)
                {
                    if (p.y < roof + 2)
                        return (int)Material.Roof;
                    return shell ? Bear((int)Material.Concrete) : -1;
                }

                if (!shell)
                {
                    // The floor slab between the storeys; its edge along the walls bears.
                    if (p.y != middle && p.y != middle + 1)
                        return -1;
                    bool edge = p.x < wall + FLOOR_EDGE || p.x >= s.x - wall - FLOOR_EDGE ||
                                p.z < wall + FLOOR_EDGE || p.z >= s.z - wall - FLOOR_EDGE;
                    return edge ? Bear((int)Material.Concrete) : (int)Material.Concrete;
                }

                // Door in the front wall (z = 0 side).
                int doorHalf = math.max(3, s.x / 10);
                if (p.z < wall && math.abs(p.x - s.x / 2) < doorHalf && p.y < math.min(middle - 3, 22))
                    return -1;

                if (Window(p, 6, middle - 6) || Window(p, middle + 6, roof - 6))
                    return -1;

                int material = p.y == middle || p.y == middle + 1 ? (int)Material.Concrete : (int)Material.Brick;
                return HouseBearing(p, middle, roof) ? Bear(material) : material;
            }

            /// <summary>
            /// Whether a house's wall voxel is in its skeleton: the corners, the piers between the
            /// windows (see Window), a beam round the floor between the storeys and the top of the wall.
            /// </summary>
            private bool HouseBearing(int3 p, int middle, int roof)
            {
                if (math.abs(p.y - middle) <= BEAM / 2 || p.y >= roof - BEAM / 2)
                    return true;
                bool across = p.x < 2 || p.x >= Size.x - 2;
                int along = across ? p.z : p.x;
                int span = across ? Size.z : Size.x;
                if (along < PIER || along >= span - PIER)
                    return true;
                // Windows run (along − 5) % 14 in [3, 10): the wall between two is a pier.
                int local = (along - 5) % 14;
                return local >= 11 || local < 2;
            }

            /// <summary>A hollow square tower with slit windows and a crown.</summary>
            private int Tower(int3 p)
            {
                const int wall = 3;
                int3 s = Size;

                if (p.y == 0)
                    return (int)Material.Concrete;

                bool shell = p.x < wall || p.x >= s.x - wall || p.z < wall || p.z >= s.z - wall;

                if (p.y >= s.y - 4)
                {
                    bool merlon = ((p.x + p.z) / 4) % 2 == 0;
                    if (!shell)
                        return p.y == s.y - 4 ? (int)Material.Wood : -1;
                    return p.y < s.y - 2 || merlon ? Bear((int)Material.Concrete) : -1;
                }

                if (!shell)
                    return p.y % 16 == 0 ? (int)Material.Wood : -1;

                int along = p.x < wall || p.x >= s.x - wall ? p.z : p.x;
                int span = p.x < wall || p.x >= s.x - wall ? s.z : s.x;
                int mid = span / 2;
                if (p.y > 4 && p.y % 16 > 5 && p.y % 16 < 13 && math.abs(along - mid) < 2)
                    return -1;

                // The skeleton: the corners and a ring beam at every floor over the ground one (each 16 voxels).
                bool bearing = along < PIER || along >= span - PIER || (p.y >= 16 && p.y % 16 < BEAM - 1);
                return bearing ? Bear((int)Material.Brick) : (int)Material.Brick;
            }

            private bool Window(int3 p, int bottom, int top)
            {
                if (p.y < bottom || p.y >= top)
                    return false;

                int along = p.x < 2 || p.x >= Size.x - 2 ? p.z : p.x;
                int span = p.x < 2 || p.x >= Size.x - 2 ? Size.z : Size.x;
                const int period = 14;
                int local = (along - 5) % period;
                return along > 5 && along < span - 5 && local >= 3 && local < 10;
            }

            /// <summary>
            /// The shade of a voxel. Bricks share a shade per brick (two voxels long, every row
            /// shifted by one) and every fourth row is mortar, so a wall reads as brickwork.
            /// </summary>
            private byte Pick(int material, int3 p)
            {
                // A load-bearing voxel (BEARING) takes its material's hard copy, when it has one.
                bool bearing = (material & BEARING) != 0;
                material &= ~BEARING;

                // A street stone comes with its shade (bits 8+, 1-based): one shade per stone.
                int forced = material >> 8;
                material &= 0xFF;

                int3 cell = p;
                if (material is (int)Material.BrickRed or (int)Material.BrickYellow)
                {
                    // Bricks two voxels long, every course shifted by one: a bond, no mortar stripes.
                    cell = new int3((p.x + p.y % 2) / 2, p.y, (p.z + p.y % 2) / 2);
                }
                else if (material == (int)Material.Slate)
                {
                    // Slates in courses, each course offset by half a slate.
                    cell = new int3((p.x + p.y % 2 * 2) / 4, p.y, p.z / 4);
                }
                else if (material is (int)Material.Glass or (int)Material.Frame or (int)Material.Door)
                {
                    cell = int3.zero;
                }
                else if (material == (int)Material.Brick)
                {
                    if (p.y % 4 == 3)
                        material = (int)Material.Mortar;
                    else
                        cell = new int3((p.x + (p.y / 4) % 2) / 2, p.y / 4, (p.z + (p.y / 4) % 2) / 2);
                }
                else if (material is (int)Material.Leaves or (int)Material.LeavesDark or (int)Material.Needles)
                {
                    // Shade by 2-voxel blocks, not voxel by voxel: neighbouring faces then share a
                    // colour and merge into big quads — a crown is a few thousand triangles, not tens.
                    cell = p / 2;
                }
                else if (material >= (int)Material.MudDry)
                {
                    // Ground and bark: 3-voxel blocks, for the same reason over a whole field.
                    cell = p / 3;
                }

                int variant = forced > 0
                    ? (forced - 1) % MeshVoxelizer.VARIANTS
                    : (int)(VoxelMath.Hash01(cell, Seed) * MeshVoxelizer.VARIANTS) % MeshVoxelizer.VARIANTS;

                // Soot and rain: long vertical streaks darken the outside of a house.
                if (forced == 0 && material is (int)Material.BrickRed or (int)Material.BrickYellow or (int)Material.Stucco
                        or (int)Material.Trim or (int)Material.Stone)
                {
                    float streak = noise.snoise(new float2((p.x + p.z) * 0.45f + Seed * 0.13f, p.y * 0.035f));
                    if (streak > 0.35f)
                        variant = 0;
                    else if (streak > 0.05f)
                        variant = math.max(0, variant - 1);
                }

                int slot = bearing ? BearingSlot(material) : -1;
                return slot >= 0
                    ? (byte)(BEARING_FIRST + slot * MeshVoxelizer.VARIANTS + variant)
                    : (byte)(1 + material * MeshVoxelizer.VARIANTS + variant);
            }
        }
    }
}
